 public Border MakeProcesses(Metrics m,bool live){var device=active==null?null:active.Copy();var wrap=new StackPanel();var head=new Grid{Margin=new Thickness(0,0,0,16)};head.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});head.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});head.Children.Add(Theme.Text(live?"GPU 进程":"GPU 进程 · 历史快照（只读）",16,Theme.Ink,false,true));var n=Theme.Text(m.Processes.Count+" 个 GPU 进程",12,Theme.Muted);Grid.SetColumn(n,1);head.Children.Add(n);wrap.Children.Add(head);string result;if(live&&device!=null&&endResults.TryGetValue(ArchiveStore.Key(device),out result)){var feedback=Theme.Text(result,12,Theme.Teal);feedback.TextWrapping=TextWrapping.Wrap;feedback.Margin=new Thickness(0,0,0,12);wrap.Children.Add(feedback);}wrap.Children.Add(ProcessRow(new[]{"GPU","PID","用户","类型","进程名","专用显存"},true,false,live));if(m.Processes.Count==0){var empty=Theme.Text(m.Gpus.Count==0?"无 NVIDIA GPU 进程":(live?"当前没有 GPU 进程":"当时没有 GPU 进程"),13,Theme.Muted);empty.Margin=new Thickness(0,16,0,4);wrap.Children.Add(empty);}else for(int i=0;i<m.Processes.Count;i++){var p=m.Processes[i];var row=ProcessRow(new[]{p.Gpu,p.Pid,p.User??"—",p.Type,p.Name,GpuTelemetry.Memory(p.Memory)},false,i%2==0,live);row.ToolTip=(p.MemorySource??"NVIDIA · 进程显存")+(string.IsNullOrEmpty(p.SharedMemory)?"":"\n共享 GPU 内存："+p.SharedMemory)+"\nC：计算进程；C/G：Windows GPU 计数器记录。";if(live){string id=device==null?"":ArchiveStore.Key(device)+"/"+p.Pid;var end=Theme.Button(pendingEnds.Contains(id)?"处理中":"结束",()=>BeginEndProcess(device,p));end.Height=32;end.MinHeight=32;end.VerticalAlignment=VerticalAlignment.Center;end.Padding=new Thickness(9,0,9,0);end.FontSize=12;end.Foreground=Theme.Red;end.BorderBrush=Theme.Line;end.Margin=new Thickness(6,5,0,5);end.ToolTip="结束前核对设备、PID 和用户，并要求确认";int pid;end.IsEnabled=device!=null&&!pendingEnds.Contains(id)&&int.TryParse(p.Pid,out pid)&&pid>4;Grid.SetColumn(end,6);row.Children.Add(end);}wrap.Children.Add(row);}if(live){v